<div class="footnote"><p><a name="Footnote_142_142" id="Footnote_142_142"></a><a href="#FNanchor_142_142"><span class="label">[142]</span></a> Among the speakers were Isabella Beecher Hooker,
Paulina Wright Davis, Minnie Swayze, Mrs. Dr. Hallock, Josephine S.
